/**
 * The game's item id of a pulled item the wish table (`@gdt/shared`
 * items.json, regenerated by scripts/wish-data.mjs) does not know yet: a
 * character or weapon released after the table's last run. Read from the
 * game data's planner tables (avatar ids for characters, weapon ids), by the
 * pull's GOOD key, else by the GOOD key of its English name. A UIGF file
 * then never needs an empty `item_id` for such an item.
 */

import { loadPlanner, type PlannerData } from '@gdt/game-data'
import { toGoodKey, type WishPull } from '@gdt/shared'

export type WishItemIdLookup = (pull: WishPull) => number | undefined

/** The lookup over loaded planner tables. Pure. */
export function wishItemIds(
  planner: Pick<PlannerData, 'characters' | 'weapons'>,
): WishItemIdLookup {
  const byKind = {
    character: (key: string) => planner.characters.get(key)?.id,
    weapon: (key: string) => planner.weapons.get(key)?.id,
  }
  return (pull) => {
    const keys = [pull.item.key, toGoodKey(pull.item.name)].filter((k): k is string => !!k)
    const kinds = pull.item.kind ? [pull.item.kind] : (['character', 'weapon'] as const)
    for (const key of keys)
      for (const kind of kinds) {
        const id = byKind[kind](key)
        if (id) return id
      }
    return undefined
  }
}

/** The lookup over the game data (its planner chunk, loaded once). */
export async function loadWishItemIds(): Promise<WishItemIdLookup> {
  return wishItemIds(await loadPlanner())
}
